		<script is:inline>
			document
				.getElementById("theme-toggle")
				?.addEventListener("click", () => {
					const isDark =
						document.documentElement.classList.toggle("dark");
					localStorage.setItem("theme", isDark ? "dark" : "light");
				});
		</script>
	</body>
</html>

