        background-repeat: no-repeat;
        background-position: left 100%;
        background-size: 0% 1px;
        transition: color 0.15s ease, background-size 0.25s ease;
    }

    .link:hover {
        color: color-mix(in oklab, var(--color-evening) 65%, var(--color-ink));
